    "bodyHtml": "<!-- Header Bar -->\r\n  <div id=\"header-placeholder\"></div>\r\n\r\n\r\n    <!-- Main Content -->\r\n    <main class=\"main-content\">\r\n        <section class=\"card\">\r\n            <div class=\"card-header\">\r\n                <span class=\"material-icons header-icon\">person</span>\r\n                <h2 class=\"card-title\">ข้อมูลส่วนตัวนิสิต (Student Personal Data)</h2>\r\n            </div>\r\n            <div class=\"card-body\">  \r\n                <div class=\"flex flex-wrap gap-[32px_50px] mb-10 max-[900px]:flex-col max-[900px]:items-center\">\r\n                    <div class=\"w-[260px] min-w-[180px] max-w-[260px] h-[336px] rounded-[15px] border border-black overflow-hidden flex items-center justify-center bg-[#f0f0f0] shrink mx-auto max-[560px]:w-full max-[560px]:max-w-[240px] max-[560px]:h-[300px] max-[360px]:max-w-[200px] max-[360px]:h-[250px]\" style=\"flex-basis: 260px;\">\r\n                        <img id=\"p-photo\" src=\"\" alt=\"Profile Photo\" class=\"w-full h-full object-cover\" style=\"display: none;\">\r\n                        <span id=\"p-icon\" class=\"material-icons text-[100px] text-gray-400\">person</span>\r\n                    </div>\r\n\r\n                    <div class=\"flex-1 min-w-[280px] flex flex-col gap-5 max-[900px]:w-full max-[900px]:min-w-0\" style=\"flex: 1 1 320px;\">\r\n                        <!-- Row 1 -->\r\n                        <div class=\"flex flex-wrap gap-[16px_24px] max-[560px]:flex-col max-[560px]:gap-4\">\r\n                            <div class=\"flex flex-col gap-[10px] min-w-[140px] max-[560px]:min-w-0 max-[560px]:w-full\" style=\"flex: 1.33 1 200px;\">\r\n                                <label class=\"text-[20px] font-semibold text-[#323639] leading-[1.35]\">ชื่อ-สกุล (ไทย)</label>\r\n                                <input class=\"input-field text-[18px] font-medium\" id=\"p-nameTh\" readonly />\r\n                            </div>\r\n                            <div class=\"flex flex-col gap-[10px] min-w-[140px] max-[560px]:min-w-0 max-[560px]:w-full\" style=\"flex: 1 1 140px;\">\r\n                                <label class=\"text-[20px] font-semibold text-[#323639] leading-[1.35]\">รหัสนิสิต</label>\r\n                                <input class=\"input-field text-[18px] font-medium\" id=\"p-studentCode\" readonly />\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- Row 2 -->\r\n                        <div class=\"flex flex-wrap gap-[16px_24px] max-[560px]:flex-col max-[560px]:gap-4\">\r\n                            <div class=\"flex flex-col gap-[10px] min-w-[140px] max-[560px]:min-w-0 max-[560px]:w-full\" style=\"flex: 1.33 1 200px;\">\r\n                                <label class=\"text-[20px] font-semibold text-[#323639] leading-[1.35]\">Name & Surname (English)</label>\r\n                                <input class=\"input-field text-[18px] font-medium\" id=\"p-nameEn\" readonly />\r\n                            </div>\r\n                            <div class=\"flex flex-col gap-[10px] min-w-[140px] max-[560px]:min-w-0 max-[560px]:w-full\" style=\"flex: 1 1 140px;\">\r\n                                <label class=\"text-[20px] font-semibold text-[#323639] leading-[1.35]\">ชั้นปีที่</label>\r\n                                <input class=\"input-field text-[18px] font-medium\" id=\"p-year\" readonly />\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- Row 3 -->\r\n                        <div class=\"flex flex-wrap gap-[16px_24px] max-[560px]:flex-col max-[560px]:gap-4\">\r\n                        <div class=\"flex flex-col gap-[10px] min-w-[140px] max-[560px]:min-w-0 max-[560px]:w-full\" style=\"flex: 1.33 1 200px;\">\r\n                            <label class=\"text-[20px] font-semibold text-[#323639] leading-[1.35]\">อาจารย์ที่ปรึกษา</label>\r\n                            <input class=\"input-field text-[18px] font-medium\" id=\"p-advisor\" readonly />\r\n                        </div>\r\n                        <div class=\"flex flex-col gap-[10px] min-w-[140px] max-[360px]:min-w-0 max-[560px]:w-full\" style=\"flex: 1.33 1 200px;\">\r\n\r\n                            <label class=\"text-[20px] font-semibold text-[#323639] leading-[1.35]\">สาขาวิชา</label>\r\n                            <input class=\"input-field text-[18px] font-medium\" id=\"p-major\" readonly />\r\n                        </div>\r\n                        <div class=\"flex flex-col gap-[10px] min-w-[140px] max-[360px]:min-w-0 max-[560px]:w-full\" style=\"flex: 1 1 140px;\">\r\n                            <label class=\"text-[20px] font-semibold text-[#323639] leading-[1.35]\">เกรดเฉลี่ย</label>\r\n                            <input class=\"input-field text-[18px] font-medium\" id=\"p-gpa\" readonly />                            \r\n                        </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"flex flex-col gap-[10px]\">\r\n                    <div class=\"flex flex-wrap gap-[16px_24px] max-[560px]:flex-col max-[560px]:gap-4\">\r\n                        <div class=\"flex flex-col gap-[10px] min-w-[140px] max-[560px]:min-w-0 max-[560px]:w-full\" style=\"flex: 1 1 160px;\">\r\n                            <label class=\"text-[20px] font-semibold text-[#323639] leading-[1.35]\">E-mail</label>\r\n                            <input class=\"input-field text-[18px] font-medium\" id=\"p-email\" readonly />\r\n                        </div>\r\n                        <div class=\"flex flex-col gap-[10px] min-w-[140px] max-[560px]:min-w-0 max-[560px]:w-full\" style=\"flex: 1 1 160px;\">\r\n                            <label class=\"text-[20px] font-semibold  text-[#323639] leading-[1.35]\">เบอร์โทร</label>\r\n                            <input class=\"input-field text-[18px] font-medium\" id=\"p-phone\" readonly />\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"flex flex-wrap gap-[16px_24px] max-[560px]:flex-col max-[560px]:gap-4\">\r\n                        <div class=\"flex flex-col gap-[10px] min-w-[140px] max-[560px]:min-w-0 max-[560px]:w-full\" style=\"flex: 1 1 160px;\">\r\n                            <label class=\"text-[20px] font-semibold text-[#323639] leading-[1.35]\">Line ID</label>\r\n                            <input class=\"input-field text-[18px] font-medium\" id=\"p-lineId\" readonly />\r\n                        </div>\r\n                        <div class=\"flex flex-col gap-[10px] min-w-[140px] max-[560px]:min-w-0 max-[560px]:w-full\" style=\"flex: 1 1 160px;\">\r\n                            <label class=\"text-[20px] font-semibold text-[#323639] leading-[1.35]\">Facebook</label>\r\n                            <input class=\"input-field text-[18px] font-medium\" id=\"p-facebook\" readonly />\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n        </section>\r\n\r\n        <!-- Edit Button -->\r\n        <div class=\"flex justify-end mt-6 max-[560px]:justify-center\">\r\n            <a href=\"/pages/status_all.html\" class=\"btn btn-primary btn-lg max-[560px]:w-full max-[560px]:justify-center no-underline inline-flex items-center gap-2\">\r\n                <span class=\"material-icons\">edit</span>\r\n                <span>ดู/แก้ไขข้อมูล</span>\r\n            </a>\r\n        </div>\r\n    </main>",
